def locate(a, key):
    left = 0
    right = len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == key:
            return mid
        if a[mid] < key:
            left = mid + 1
        else:
            right = mid - 1
    return -1
